#!/usr/bin/env node
"use strict";

/**
 * Guard: forbid runtime-interpolated Tailwind class fragments. With no
 * safelist in tailwind.config.ts, classes like `bg-${color}-50` or
 * `h-[${size}px]` are never generated by the JIT — the UI silently loses
 * styling in production. Interpolating a COMPLETE class string chosen from
 * static literals (`${active ? "opacity-60" : ""}`) is fine and not flagged.
 * Allowlist: scripts/audit-guards-allowlist.json (dynamicTailwind).
 */

const fs = require("fs");
const path = require("path");

const SRC = path.join(__dirname, "..", "src");
const ALLOWLIST = JSON.parse(
  fs.readFileSync(path.join(__dirname, "audit-guards-allowlist.json"), "utf8"),
).dynamicTailwind;

// Matches Tailwind utility-prefix interpolation: bg-${...}, text-${...}, line-clamp-${...},
// bg-gradient-to-${...}, etc. Uses a curated prefix list to avoid false positives from
// JSX key/id patterns like key={`discount-${i}`}, key={`b-${k}`} that share the `-${` shape.
// Must appear after whitespace, backtick, quote, or open-paren/brace so it catches class-start
// tokens while excluding mid-template `-${` continuations (e.g. `${index}-child-${childIndex}`).
const PREFIX_RE =
  /(?:^|[\s`'"({])(?:bg-gradient-to|bg|text|border|ring|shadow|outline|fill|stroke|from|via|to|gradient-to|line-clamp|px|py|pt|pb|pl|pr|p|gap|space-x|space-y|min-w|min-h|max-w|max-h|w|h|rounded|opacity|scale|rotate|font|leading|tracking|col|row|flex|grid|top|bottom|left|right|inset|hover|focus|active|group|peer|2xl|xl|sm|md|lg)-\$\{/;

// Arbitrary-value interpolation: h-[${...}], w-[${...}px], max-h-[${...}].
// Requires a Tailwind-prefix before the `[` so it doesn't match unrelated bracket
// expressions like `[${source}]` in error log strings or `[${selected}]` in selectors.
// Checked on ALL lines (not gated on inClassName) because dynamic-sized class variables
// like `const cls = \`h-[${size}px]\`` are just as dangerous as inline className attrs.
const ARBITRARY_TAILWIND_RE = /[\w:-]+-\[[^\]\n]*\$\{/;

function walk(dir, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(entry.name) && !/\.test\.(ts|tsx)$/.test(entry.name))
      out.push(p);
  }
  return out;
}

const violations = [];
for (const file of walk(SRC, [])) {
  const rel = path.relative(path.join(__dirname, ".."), file).replace(/\\/g, "/");
  if (ALLOWLIST[rel]) continue;
  const lines = fs.readFileSync(file, "utf8").split("\n");
  let inClassName = false;
  lines.forEach((line, i) => {
    if (/className\s*=/.test(line)) inClassName = true;
    // PREFIX_RE is gated on className context to reduce false positives.
    // ARBITRARY_TAILWIND_RE is always checked: h-[${size}px] in a variable
    // assigned for later use as className is just as broken in production.
    if (
      (inClassName && PREFIX_RE.test(line)) ||
      ARBITRARY_TAILWIND_RE.test(line)
    ) {
      violations.push(`${rel}:${i + 1}: ${line.trim().slice(0, 120)}`);
    }
    // Heuristic close: attribute ends when the line closes the JSX expression.
    if (inClassName && /[}>]\s*$/.test(line)) inClassName = false;
  });
}

if (violations.length > 0) {
  console.error(
    `Dynamic-Tailwind guard: ${violations.length} violation(s). Interpolate complete class strings from static literals, or use style props for numeric values.`,
  );
  for (const v of violations) console.error(`  ${v}`);
  process.exit(1);
}
console.log("Dynamic-Tailwind guard: clean.");
